	switch rv.Kind() {
	case reflect.Pointer, reflect.Slice, reflect.Map:
		if rv.IsNil() {
			return nil
		}
		if rv.Kind() == reflect.Pointer {
			v = rv.Elem().Interface()
		}
	}
	s := fmt.Sprintf("%v", v)
	return &s
